                writer.WriteString("type", "socketClosed");
                break;
            case LiveEvent.Message x:
                writer.WriteString("type", "message");
                ViewJson.Write(writer, "message", x.MessageValue, options);
                break;
            case LiveEvent.Timer x:
                writer.WriteString("type", "timer");
                ViewJson.Write(writer, "name", x.Name, options);
                break;
            case LiveEvent.Follow x:
                writer.WriteString("type", "follow");
                ViewJson.Write(writer, "pointer", x.Pointer, options);
                break;
            case LiveEvent.Remote x:
                writer.WriteString("type", "remote");
                ViewJson.Write(writer, "on", x.On, options);
                break;
            case LiveEvent.Output x:
                writer.WriteString("type", "output");
                ViewJson.Write(writer, "id", x.Id, options);
                ViewJson.Write(writer, "on", x.On, options);
                ViewJson.Write(writer, "take", x.Take, options);
                break;
            case LiveEvent.Playback x:
                writer.WriteString("type", "playback");
                ViewJson.Write(writer, "audio", x.Audio, options);
                ViewJson.Write(writer, "video", x.Video, options);
                ViewJson.Write(writer, "videoLive", x.VideoLive, options);
                break;
            case LiveEvent.Changed x:
                writer.WriteString("type", "changed");
                break;
            case LiveEvent.Control x:
                writer.WriteString("type", "control");
                ViewJson.Write(writer, "sessionId", x.SessionId, options);
                break;
            case LiveEvent.Release x:
                writer.WriteString("type", "release");
                break;
            case LiveEvent.Set x:
                writer.WriteString("type", "set");
                ViewJson.Write(writer, "change", x.Change, options);
                break;
            case LiveEvent.Unknown x:
                writer.WriteString("type", x.Type);
                break;
        }
        writer.WriteEndObject();
    }
}

